mapper.select:
SELECT cm.id, cm.session_id AS sessionId, cm.message_seq AS messageSeq, cm.user_id AS userId, su.user_name AS userName, cm.content, cm.role, cm.model_id AS modelId, cm.model_selection_mode AS modelSelectionMode, cm.model_revision AS modelRevision, cm.route_reason_code AS routeReasonCode, cm.route_policy_revision AS routePolicyRevision, cm.candidate_snapshot_hash AS candidateSnapshotHash, cm.total_tokens AS totalTokens, cm.input_tokens AS inputTokens, cm.output_tokens AS outputTokens, cm.deduct_tokens AS deductTokens, cm.model_name AS modelName, cm.call_status AS callStatus, cm.request_id AS requestId, cm.error_code AS errorCode, cm.error_message AS errorMessage, cm.create_time AS createTime, cm.update_time AS updateTime FROM chat_message cm LEFT JOIN sys_user su ON su.user_id = cm.user_id
AND cm.session_id = #{bo.sessionId}
AND cm.user_id = #{bo.userId}
AND su.user_name LIKE CONCAT('%', #{bo.userName}, '%')
AND cm.content LIKE CONCAT('%', #{bo.content}, '%')
AND cm.role = #{bo.role}
AND cm.call_status = #{bo.callStatus}
AND cm.total_tokens = #{bo.totalTokens}
AND cm.model_name LIKE CONCAT('%', #{bo.modelName}, '%')
ORDER BY cm.message_seq ASC, cm.id ASC

SELECT id, session_id, message_seq, content, role, call_status, request_id
FROM chat_message
WHERE session_id = #{sessionId}

    AND message_seq > #{coveredMessageSeq}


    AND (request_id IS NULL OR request_id != #{requestId})

AND role IN (#{userRole}, #{assistantRole})
AND call_status != #{failedStatus}
ORDER BY message_seq DESC, id DESC
LIMIT #{limit}
